<script setup lang="ts">
type Star={id:number;x:number;y:number;duration:number;delay:number;bright:boolean}
const stars=ref<Star[]>([]),paused=ref(false)
let reduced:MediaQueryList|undefined
function position(){const x=3+Math.random()*94;const height=x<7?40:x<43?90:x<65?94-x:27;return {x,y:3+Math.random()*(height-3)}}
function relocate(star:Star){if(!paused.value&&!reduced?.matches)Object.assign(star,position())}
function visibility(){paused.value=document.hidden}
onMounted(()=>{reduced=window.matchMedia('(prefers-reduced-motion: reduce)');stars.value=Array.from({length:window.innerWidth<800?18:34},(_,id)=>({id,...position(),duration:3.8+Math.random()*5,delay:-Math.random()*9,bright:Math.random()<.25}));visibility();document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>document.removeEventListener('visibilitychange',visibility))
</script>
<template><div class="cosmic-motion" :class="{paused}" aria-hidden="true"><span v-for="star in stars" :key="star.id" class="cosmic-star" :class="{bright:star.bright}" :style="{left:`${star.x}%`,top:`${star.y}%`,animationDuration:`${star.duration}s`,animationDelay:`${star.delay}s`}" @animationiteration="relocate(star)"/><span class="sun-glow"/><span class="sun-rays"/><span class="sun-flare"/></div></template>
<style scoped>
.cosmic-motion{position:absolute;top:0;left:0;width:100%;aspect-ratio:8/3;overflow:hidden;pointer-events:none;contain:layout paint}.cosmic-star{position:absolute;width:2.5px;height:2.5px;border-radius:50%;background:#e1efff;box-shadow:0 0 6px #d4eaff,0 0 13px #71a9ffbb;animation:twinkle 5s ease-in-out infinite}.bright{width:4px;height:4px;background:#fff6e0}.bright::before,.bright::after{content:'';position:absolute;top:1px;left:-6px;width:16px;height:1px;background:linear-gradient(90deg,transparent,#d4e9ff,transparent)}.bright::after{transform:rotate(90deg)}.sun-glow,.sun-rays,.sun-flare{position:absolute;left:93.7%;top:47.5%;transform:translate(-50%,-50%);border-radius:50%;animation:breathe 9s ease-in-out infinite}.sun-glow{width:18%;aspect-ratio:1;background:radial-gradient(circle,#fff5c52b,#ffbd5a25 14%,#ff8a3112 36%,transparent 68%)}.sun-rays{width:13%;aspect-ratio:1;background:repeating-conic-gradient(transparent 0deg 24deg,#ffcc7520 27deg,transparent 30deg 57deg);mask-image:radial-gradient(circle,transparent 5%,#000 16%,transparent 64%);animation:corona 85s linear infinite;opacity:.5}.sun-flare{width:21%;height:1.6%;background:radial-gradient(ellipse,#fff3d650,#ffbe4b1c 30%,transparent 72%)}@keyframes twinkle{0%,90%,100%{opacity:0;transform:scale(.4)}45%{opacity:1;transform:scale(1.5)}65%{opacity:.45;transform:scale(.9)}}@keyframes breathe{0%,100%{opacity:.35;transform:translate(-50%,-50%) scale(.94)}50%{opacity:.75;transform:translate(-50%,-50%) scale(1.06)}}@keyframes corona{from{transform:translate(-50%,-50%) rotate(0)}to{transform:translate(-50%,-50%) rotate(360deg)}}.paused *{animation-play-state:paused!important}@media(max-width:800px){.cosmic-motion{width:calc(460px * 8 / 3);height:460px;left:calc((100% - 460px * 8 / 3) * .66)}}@media(prefers-reduced-motion:reduce){.cosmic-motion *{animation:none!important}.cosmic-star{opacity:.4}.sun-glow,.sun-flare{opacity:.5}}
</style>
